script:
(function () {
  'use strict';

  var deviceSelectA = document.getElementById('deviceSelectA');
  var deviceSelectB = document.getElementById('deviceSelectB');
  var btnStart = document.getElementById('btnStart');
  var btnStop = document.getElementById('btnStop');
  var btnSwap = document.getElementById('btnSwap');
  var btnLayout = document.getElementById('btnLayout');
  var btnDownload = document.getElementById('btnDownload');
  var dualPreview = document.getElementById('dualPreview');
  var videoA = document.getElementById('videoA');
  var videoB = document.getElementById('videoB');
  var stillA = document.getElementById('stillA');
  var stillB = document.getElementById('stillB');
  var wrapA = document.getElementById('wrapA');
  var wrapB = document.getElementById('wrapB');
  var labelA = document.getElementById('labelA');
  var labelB = document.getElementById('labelB');
  var placeholderA = document.getElementById('placeholderA');
  var placeholderB = document.getElementById('placeholderB');
  var captureControls = document.getElementById('captureControls');
  var btnCaptureA = document.getElementById('btnCaptureA');
  var btnCaptureB = document.getElementById('btnCaptureB');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var inputNameA = document.getElementById('inputNameA');
  var inputNameB = document.getElementById('inputNameB');
  var scorecard = document.getElementById('scorecard');
  var btnResetScores = document.getElementById('btnResetScores');
  var scoreVerdict = document.getElementById('scoreVerdict');
  var scoreTotalA = document.getElementById('scoreTotalA');
  var scoreTotalB = document.getElementById('scoreTotalB');
  var scoreTotalALabel = document.getElementById('scoreTotalALabel');
  var scoreTotalBLabel = document.getElementById('scoreTotalBLabel');
  var scoreWon = document.getElementById('scoreWon');
  var scoreGap = document.getElementById('scoreGap');
  var scoreOrder = document.getElementById('scoreOrder');
  var scoreReading = document.getElementById('scoreReading');

  var CHECKS = [
    ['detail', 'Fine detail and sharpness'],
    ['wb', 'White balance and skin tones'],
    ['backlit', 'Exposure with a backlit window'],
    ['lowlight', 'Low light noise'],
    ['focus', 'Autofocus'],
    ['framing', 'Framing and eyeline'],
  ];

  var streamA = null, streamB = null;
  var starting = false;
  var captureMode = false; // true once a simultaneous second stream has failed
  var swapped = false; // true = Camera B shown on the left / top
  var canvas = document.createElement('canvas');
  var ctx = canvas.getContext('2d');
  var stillAUrl = null, stillBUrl = null;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>That camera couldn’t be found.</strong> Make sure it’s connected, then reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>That camera is already in use.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function nameOf(which) {
    var v = ((which === 'A' ? inputNameA : inputNameB).value || '').trim();
    return v || 'Camera ' + which;
  }

  function updateNames() {
    labelA.textContent = inputNameA.value.trim() ? 'A: ' + inputNameA.value.trim() : 'Camera A';
    labelB.textContent = inputNameB.value.trim() ? 'B: ' + inputNameB.value.trim() : 'Camera B';
    scoreTotalALabel.textContent = nameOf('A') + ' total';
    scoreTotalBLabel.textContent = nameOf('B') + ' total';
    btnCaptureA.textContent = 'Capture ' + nameOf('A');
    btnCaptureB.textContent = 'Capture ' + nameOf('B');
    updateScores();
  }

  // Moderate resolution on both requests -- running two live streams
  // roughly doubles bandwidth and CPU cost, per this tool's own spec.
  function requestCamera(deviceId) {
    var constraint = { width: { ideal: 640 }, height: { ideal: 480 } };
    if (deviceId) constraint.deviceId = { exact: deviceId };
    return navigator.mediaDevices.getUserMedia({ video: constraint, audio: false });
  }

  function stopStreamVar(name) {
    var s = name === 'A' ? streamA : streamB;
    if (s) {
      s.getTracks().forEach(function (t) { t.stop(); });
      if (name === 'A') streamA = null; else streamB = null;
    }
  }

  function resetPanel(which) {
    var video = which === 'A' ? videoA : videoB;
    var still = which === 'A' ? stillA : stillB;
    var wrap = which === 'A' ? wrapA : wrapB;
    var placeholder = which === 'A' ? placeholderA : placeholderB;
    video.srcObject = null;
    video.style.display = '';
    still.style.display = 'none';
    wrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
  }

  function stopAll() {
    stopStreamVar('A');
    stopStreamVar('B');
    resetPanel('A');
    resetPanel('B');
    captureMode = false;
    captureControls.style.display = 'none';
    btnStop.disabled = true;
    btnSwap.disabled = true;
    btnLayout.disabled = true;
    btnDownload.disabled = true;
  }

  function populateSelects(devices) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    [deviceSelectA, deviceSelectB].forEach(function (sel, idx) {
      var keep = sel.value;
      sel.innerHTML = '';
      if (!cams.length) {
        var opt = document.createElement('option');
        opt.value = '';
        opt.textContent = 'No cameras found';
        sel.appendChild(opt);
        sel.disabled = true;
        return;
      }
      cams.forEach(function (d, i) {
        var o = document.createElement('option');
        o.value = d.deviceId;
        o.textContent = d.label || ('Camera ' + (i + 1));
        sel.appendChild(o);
      });
      // Default A/B to two different cameras where more than one exists.
      if (keep && cams.some(function (d) { return d.deviceId === keep; })) {
        sel.value = keep;
      } else if (cams.length > 1) {
        sel.selectedIndex = idx === 1 ? 1 : 0;
      }
      sel.disabled = false;
    });
  }

  function refreshDeviceLists() {
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return Promise.resolve();
    return navigator.mediaDevices.enumerateDevices().then(populateSelects).catch(function () {});
  }

  function startLivePanel(which, deviceId) {
    var video = which === 'A' ? videoA : videoB;
    var wrap = which === 'A' ? wrapA : wrapB;
    var placeholder = which === 'A' ? placeholderA : placeholderB;
    return requestCamera(deviceId).then(function (stream) {
      if (which === 'A') streamA = stream; else streamB = stream;
      video.srcObject = stream;
      placeholder.style.display = 'none';
      wrap.classList.add('is-active');
      return video.play().catch(function () {});
    });
  }

  function enterCaptureMode() {
    captureMode = true;
    stopStreamVar('A');
    stopStreamVar('B');
    resetPanel('A');
    resetPanel('B');
    captureControls.style.display = 'flex';
    setDiagnostic([{ sev: 'warn', html: '<strong>This device can only use one camera at a time,</strong> so live simultaneous comparison isn’t possible here. Capture each camera separately below instead — they’ll display side by side for comparison.' }]);
    btnStop.disabled = false;
    btnSwap.disabled = false;
    btnLayout.disabled = false;
    btnDownload.disabled = false;
  }

  function captureStill(which) {
    var deviceId = (which === 'A' ? deviceSelectA : deviceSelectB).value;
    var video = which === 'A' ? videoA : videoB;
    var still = which === 'A' ? stillA : stillB;
    var wrap = which === 'A' ? wrapA : wrapB;
    var placeholder = which === 'A' ? placeholderA : placeholderB;
    setDiagnostic([{ sev: '', html: 'Requesting ' + escapeHtml(nameOf(which)) + '…' }]);
    return requestCamera(deviceId)
      .then(function (stream) {
        video.srcObject = stream;
        return video.play().catch(function () {}).then(function () {
          return new Promise(function (resolve) { setTimeout(resolve, 250); }); // let auto-exposure settle briefly
        }).then(function () {
          var w = video.videoWidth || 640, h = video.videoHeight || 480;
          canvas.width = w;
          canvas.height = h;
          ctx.drawImage(video, 0, 0, w, h);
          stream.getTracks().forEach(function (t) { t.stop(); });
          video.srcObject = null;
          return new Promise(function (resolve) {
            canvas.toBlob(function (blob) { resolve(blob); }, 'image/png');
          });
        });
      })
      .then(function (blob) {
        var url = URL.createObjectURL(blob);
        if (which === 'A') { if (stillAUrl) URL.revokeObjectURL(stillAUrl); stillAUrl = url; }
        else { if (stillBUrl) URL.revokeObjectURL(stillBUrl); stillBUrl = url; }
        still.src = url;
        still.style.display = 'block';
        video.style.display = 'none';
        placeholder.style.display = 'none';
        wrap.classList.add('is-active');
        setDiagnostic([{ sev: 'ok', html: '<strong>' + escapeHtml(nameOf(which)) + ' captured.</strong> Capture the other camera to compare, or download the comparison.' }]);
      })
      .catch(function (err) {
        setDiagnostic([describeError(err)]);
      });
  }

  function startComparison() {
    if (starting) return;
    starting = true;
    stopAll();
    setDiagnostic([{ sev: '', html: 'Requesting ' + escapeHtml(nameOf('A')) + '…' }]);
    btnStart.disabled = true;

    startLivePanel('A', deviceSelectA.value)
      .then(function () {
        setDiagnostic([{ sev: '', html: escapeHtml(nameOf('A')) + ' is live. Requesting ' + escapeHtml(nameOf('B')) + '…' }]);
        return startLivePanel('B', deviceSelectB.value);
      })
      .then(function () {
        setDiagnostic([{ sev: 'ok', html: '<strong>Both cameras are live.</strong> Use Swap to switch sides, or Download Comparison to save a combined image.' }]);
        btnStop.disabled = false;
        btnSwap.disabled = false;
        btnLayout.disabled = false;
        btnDownload.disabled = false;
        return refreshDeviceLists();
      })
      .catch(function (err) {
        // A conflict on the SECOND request (device already locked by the
        // first) is the expected "only one active camera" case this
        // tool's spec explicitly calls out -- fall back to captures
        // rather than just showing an error.
        if (err && (err.name === 'NotReadableError' || err.name === 'TrackStartError' || err.name === 'OverconstrainedError')) {
          enterCaptureMode();
        } else {
          setDiagnostic([describeError(err)]);
          stopAll();
        }
      })
      .finally(function () {
        starting = false;
        btnStart.disabled = false;
      });
  }

  // Swapping moves each panel (live feed or still, plus its label) to the
  // other side without reopening either camera, so names and
  // scores stay attached to the right device.
  function swap() {
    swapped = !swapped;
    wrapA.style.order = swapped ? '2' : '';
    wrapB.style.order = swapped ? '1' : '';
    updateScores();
  }

  function toggleLayout() {
    var stacked = dualPreview.classList.toggle('stacked');
    btnLayout.textContent = stacked ? 'Horizontal Split' : 'Vertical Split';
    updateScores();
  }

  function sourceFor(which) {
    if (captureMode) {
      var still = which === 'A' ? stillA : stillB;
      return still.style.display === 'block' ? still : null;
    }
    var v = which === 'A' ? videoA : videoB;
    return v.srcObject && v.videoWidth ? v : null;
  }

  function downloadComparison() {
    var stacked = dualPreview.classList.contains('stacked');
    var order = swapped ? ['B', 'A'] : ['A', 'B'];
    var srcs = order.map(function (w) { return captureMode ? (w === 'A' ? stillA : stillB) : (w === 'A' ? videoA : videoB); });
    var dims = srcs.map(function (s) {
      return { w: s.videoWidth || s.naturalWidth || 640, h: s.videoHeight || s.naturalHeight || 480 };
    });
    var outCanvas = document.createElement('canvas');
    var outCtx = outCanvas.getContext('2d');
    if (stacked) {
      outCanvas.width = Math.max(dims[0].w, dims[1].w);
      outCanvas.height = dims[0].h + dims[1].h;
    } else {
      outCanvas.width = dims[0].w + dims[1].w;
      outCanvas.height = Math.max(dims[0].h, dims[1].h);
    }
    outCtx.fillStyle = '#000';
    outCtx.fillRect(0, 0, outCanvas.width, outCanvas.height);
    var pos = stacked ? [[0, 0], [0, dims[0].h]] : [[0, 0], [dims[0].w, 0]];
    srcs.forEach(function (s, i) {
      if (sourceFor(order[i])) outCtx.drawImage(s, pos[i][0], pos[i][1], dims[i].w, dims[i].h);
    });
    outCanvas.toBlob(function (blob) {
      if (!blob) return;
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url;
      a.download = 'camera-comparison.png';
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
    }, 'image/png');
  }

  // ---------- Scorecard ----------

  function buildScorecard() {
    scorecard.innerHTML = CHECKS.map(function (c) {
      return '<div class="tool-row">' + ['A', 'B'].map(function (w) {
        var id = 'score-' + c[0] + '-' + w;
        return '<div class="tool-field slider-field"><label for="' + id + '">' + escapeHtml(c[1]) + ': <span data-name="' + w + '">' + escapeHtml(nameOf(w)) + '</span></label>' +
          '<div class="slider-row"><input type="range" id="' + id + '" data-check="' + c[0] + '" data-cam="' + w + '" min="1" max="5" step="1" value="3">' +
          '<span class="slider-value" data-out="' + id + '">3</span></div></div>';
      }).join('') + '</div>';
    }).join('');
  }

  function scoreOf(check, cam) {
    var el = scorecard.querySelector('input[data-check="' + check + '"][data-cam="' + cam + '"]');
    return el ? parseInt(el.value, 10) || 0 : 0;
  }

  function updateScores() {
    scorecard.querySelectorAll('span[data-name]').forEach(function (s) { s.textContent = nameOf(s.getAttribute('data-name')); });
    scorecard.querySelectorAll('input[type=range]').forEach(function (inp) {
      var out = scorecard.querySelector('span[data-out="' + inp.id + '"]');
      if (out) out.textContent = inp.value;
    });
    var ta = 0, tb = 0, wa = 0, wb = 0, gap = 0, gapName = '';
    CHECKS.forEach(function (c) {
      var a = scoreOf(c[0], 'A'), b = scoreOf(c[0], 'B');
      ta += a; tb += b;
      if (a > b) wa++; else if (b > a) wb++;
      if (Math.abs(a - b) > gap) { gap = Math.abs(a - b); gapName = c[1] + ' (' + (a > b ? nameOf('A') : nameOf('B')) + ' +' + gap + ')'; }
    });
    var max = CHECKS.length * 5;
    scoreTotalA.textContent = ta + ' / ' + max;
    scoreTotalB.textContent = tb + ' / ' + max;
    scoreWon.textContent = wa + '–' + wb;
    scoreGap.textContent = gap ? gapName : 'None';
    var stacked = dualPreview.classList.contains('stacked');
    var first = swapped ? nameOf('B') : nameOf('A'), second = swapped ? nameOf('A') : nameOf('B');
    scoreOrder.textContent = first + (stacked ? ' on top, ' : ' left, ') + second + (stacked ? ' below' : ' right');
    var diff = Math.abs(ta - tb);
    var winner = ta > tb ? nameOf('A') : nameOf('B');
    if (!diff) {
      scoreVerdict.textContent = 'Tie';
      scoreReading.textContent = 'Both cameras score the same overall. Decide on the check that matters most to you, or rerun the test in harder light (a bright window behind you, or an evening lamp).';
    } else {
      scoreVerdict.textContent = winner + ' by ' + diff;
      scoreReading.textContent = diff <= 2
        ? winner + ' leads by only ' + diff + ' of ' + max + ' points: close enough that lighting or framing changes can flip the result, so swap sides and rescore before deciding.'
        : (diff <= 5
          ? winner + ' is clearly ahead (' + Math.round(Math.max(ta, tb) / max * 100) + '% vs ' + Math.round(Math.min(ta, tb) / max * 100) + '%), winning ' + Math.max(wa, wb) + ' of ' + CHECKS.length + ' checks.'
          : winner + ' wins decisively by ' + diff + ' points out of ' + max + '; the gap is large enough to be worth acting on.');
    }
  }

  // ---------- Wiring ----------

  btnStart.addEventListener('click', startComparison);
  btnStop.addEventListener('click', function () {
    stopAll();
    setDiagnostic([{ sev: '', html: 'Stopped. Click <strong>Start Comparison</strong> to try again.' }]);
  });
  btnSwap.addEventListener('click', swap);
  btnLayout.addEventListener('click', toggleLayout);
  btnDownload.addEventListener('click', downloadComparison);
  btnCaptureA.addEventListener('click', function () { captureStill('A'); });
  btnCaptureB.addEventListener('click', function () { captureStill('B'); });
  [inputNameA, inputNameB].forEach(function (el) { el.addEventListener('input', updateNames); });
  scorecard.addEventListener('input', updateScores);
  btnResetScores.addEventListener('click', function () {
    scorecard.querySelectorAll('input[type=range]').forEach(function (inp) { inp.value = 3; });
    updateScores();
  });

  window.addEventListener('pagehide', function () {
    stopAll();
    if (stillAUrl) { URL.revokeObjectURL(stillAUrl); stillAUrl = null; }
    if (stillBUrl) { URL.revokeObjectURL(stillBUrl); stillBUrl = null; }
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopAll();
  });

  buildScorecard();
  updateNames();
  refreshDeviceLists();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong> Try the latest version of Chrome, Firefox, Edge, or Safari.' }]);
    btnStart.disabled = true;
  }
})();
